"#!/bin/zsh\n\nset -e # Exit immediately if a command exits with a non-zero status.\n\necho \"========================================\"\necho \"🚀 Starting plusmagi-playwright Build Process...\"\necho \"========================================\"\\n\\n# 1. Install Dependencies (Using npm ci for clean builds)\nnpm install --ci\nif [ $? -ne 0 ]; then\n	echo \"[ERROR] Dependency installation failed. Check package.json and run: npm install --ci\"\n	exit 1\nfi\\n\\necho \"✅ Dependencies installed successfully.\"\n\n# 2. Compile TypeScript Source Code\necho \"➡️ Compiling TypeScript using tsc...\";\ntsc --project tsconfig.json # <-- Uses the newly created and updated config file\nif [ $? -ne 0 ]; then\n	echo \"[ERROR] TypeScript compilation failed. Check tsconfig.json or source files.\"\n	exit 1\nfi\n\\necho \"✅ TypeScript compilation successful! Compiled assets are in dist/.\"\n\n# 3. Optional: Run Playwright Tests (Commented out for clean build script)\n# echo \"Running tests...\";\n# npx playwright test --project=\"Google Chrome\"\necho \"✨ Build process complete! Core services compiled to ./dist/ and ready for packaging.\"
"